import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { FormBuilder, Validators, ReactiveFormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ReactiveFormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export default class AppComponent {
  private readonly fb = inject(FormBuilder);
  private readonly http = inject(HttpClient);

  readonly contactForm = this.fb.group({
    name: ['', [Validators.required]],
    email: ['', [Validators.required, Validators.email]],
    message: ['', [Validators.required, Validators.minLength(10)]],
  });
  readonly f = this.contactForm.controls;

  readonly isSubmitting = signal(false);
  readonly successMessage = signal('');
  readonly errorMessage = signal('');

  submit(event?: Event): void {
    event?.preventDefault();
    event?.stopPropagation();

    this.successMessage.set('');
    this.errorMessage.set('');
    this.contactForm.markAllAsTouched();
    if (this.contactForm.invalid || this.isSubmitting()) {
      return;
    }

    this.isSubmitting.set(true);
    // The callbacks run after submit() has returned; their signal writes are what refresh the OnPush view.
    this.http.post('https://jsonplaceholder.typicode.com/posts', this.contactForm.value).subscribe({
      next: () => {
        this.isSubmitting.set(false);
        this.successMessage.set('Your message has been sent. Thank you!');
        this.contactForm.reset();
      },
      error: () => {
        this.isSubmitting.set(false);
        this.errorMessage.set('Something went wrong. Please try again.');
      },
    });
  }
}

export { AppComponent };
